On pull requests that touch terraform/, run a plan with OIDC credentials and post the output as a PR comment so reviewers can see the change before approving: name: Terraform Plan on: pull_request: paths: - "terraform/**" jobs: plan: runs-on: ubuntu-latest permissions: id-token: write contents: read pull-requests: write steps: - uses: actions/checkout@v4 - uses: aws-actions/configure-aws-credentials@v4 with: role-to-assume: ${{ secrets.TERRAFORM_ROLE_ARN }} aws-region: us-east-2 - uses: hashicorp/setup-terraform@v3 with: terraform_version: "1.9" - name: Terraform fmt run: terraform fmt -check -recursive working-directory: terraform - name: Terraform plan id: plan run: | terraform plan -no-color -out=tfplan 2>&1 | tee plan.txt echo 'PLAN<<EOF' >> $GITHUB_OUTPUT cat plan.txt >> $GITHUB_OUTPUT echo 'EOF' >> $GITHUB_OUTPUT working-directory: terraform - name: Post plan to PR uses: actions/github-script@v7 with: script: | const output = `## Terraform Plan

\`\`\`hcl
${{ steps.plan.outputs.PLAN }}
\`\`\``; github.rest.issues.createComment({ issue_number: context.issue.number, owner: context.repo.owner, repo: context.repo.repo, body: output, });

name: Terraform on: pull_request: paths: - "live/**" - "modules/**" jobs: plan: runs-on: ubuntu-latest steps: - uses: actions/checkout@v4 - name: Setup Terragrunt uses: gruntwork-io/terragrunt-action@v2 - name: Configure AWS credentials uses: aws-actions/configure-aws-credentials@v4 with: role-to-assume: ${{ secrets.TERRAFORM_ROLE_ARN }} aws-region: us-east-2 - name: Terragrunt Format run: terragrunt hclfmt --terragrunt-check - name: Terragrunt Plan id: plan run: | terragrunt run-all plan -no-color 2>&1 | tee plan.txt echo 'PLAN_OUTPUT<<EOF' >> $GITHUB_ENV cat plan.txt >> $GITHUB_ENV echo 'EOF' >> $GITHUB_ENV - name: Post Plan to PR uses: actions/github-script@v7 with: script: | const output = process.env.PLAN_OUTPUT; github.rest.issues.createComment({ issue_number: context.issue.number, owner: context.repo.owner, repo: context.repo.repo, body: `## Terraform Plan

\`\`\`
${output}
\`\`\`` });
